package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original source and metadata of the exact Salesforce-admitted contract.
func TestRunJSONEOFEdgeContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonEOFEdges67.cls"), "@IsTest private class GladeJsonEOFEdges67 {\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every edge operation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Edge observation exceeds bound');verifyExactEdges(rows);}\nprivate static void observe(String input){\nList<Object> rows=new List<Object>();Map<String,Object> row=new Map<String,Object>{'input'=>input,'utf16Length'=>input.length()};\ntry{Object value=JSON.deserializeUntyped(input);row.put('value',value);row.put('returned',true);}\ncatch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\nrows.add(row);finish(rows,1);\n}\n@IsTest static void bmpObjectKey(){observe('{\"猫\":');}\n@IsTest static void astralObjectKey(){observe('{\"😀\":');}\n@IsTest static void astralArrayValue(){observe('[\"😀\",');}\n@IsTest static void escapedAstralKey(){observe('{\"\\\\uD83D\\\\uDE00\":');}\n@IsTest static void crlfBeforeObject(){observe('\\r\\n{\"a\":');}\n@IsTest static void crlfAfterColon(){observe('{\"a\":\\r\\n');}\n@IsTest static void crAfterColon(){observe('{\"a\":\\r');}\n@IsTest static void crlfNestedObject(){observe('{\"a\":{\\r\\n\"b\":');}\n@IsTest static void nestedObjectAfterNumber(){observe('{\"a\":[{\"b\":1');}\n@IsTest static void nestedArrayAfterComma(){observe('{\"a\":[1,');}\n@IsTest static void nestedObjectAfterComma(){observe('{\"a\":{\"b\":1,');}\n@IsTest static void nestedStringTokenEOF(){observe('{\"a\":{\"b\":\"unterminated');}\n\nprivate static void verifyExactEdges(List<Object> rows){\nSystem.assert(rows.size()>0,'Expected at least one observed row');\nMap<String,Object> first=(Map<String,Object>)rows[0];\nString expectedJSON;\nif((String)first.get('input') == '[\"😀\",')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between ARRAY entries at [line:1, column:13]\",\"type\":\"System.JSONException\",\"utf16Length\":6,\"input\":\"[\\\\\"😀\\\\\",\"}]';\nelse if((String)first.get('input') == '{\"😀\":')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:13]\",\"type\":\"System.JSONException\",\"utf16Length\":6,\"input\":\"{\\\\\"😀\\\\\":\"}]';\nelse if((String)first.get('input') == '{\"猫\":')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:11]\",\"type\":\"System.JSONException\",\"utf16Length\":5,\"input\":\"{\\\\\"猫\\\\\":\"}]';\nelse if((String)first.get('input') == '{\"a\":\\r')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:2, column:7]\",\"type\":\"System.JSONException\",\"utf16Length\":6,\"input\":\"{\\\\\"a\\\\\":\\\\r\"}]';\nelse if((String)first.get('input') == '{\"a\":\\r\\n')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:2, column:8]\",\"type\":\"System.JSONException\",\"utf16Length\":7,\"input\":\"{\\\\\"a\\\\\":\\\\r\\\\n\"}]';\nelse if((String)first.get('input') == '\\r\\n{\"a\":')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:2, column:13]\",\"type\":\"System.JSONException\",\"utf16Length\":7,\"input\":\"\\\\r\\\\n{\\\\\"a\\\\\":\"}]';\nelse if((String)first.get('input') == '{\"a\":{\\r\\n\"b\":')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:2, column:17]\",\"type\":\"System.JSONException\",\"utf16Length\":12,\"input\":\"{\\\\\"a\\\\\":{\\\\r\\\\n\\\\\"b\\\\\":\"}]';\nelse if((String)first.get('input') == '{\"\\\\uD83D\\\\uDE00\":')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:33]\",\"type\":\"System.JSONException\",\"utf16Length\":16,\"input\":\"{\\\\\"\\\\\\\\uD83D\\\\\\\\uDE00\\\\\":\"}]';\nelse if((String)first.get('input') == '{\"a\":[1,')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between ARRAY entries at [line:1, column:17]\",\"type\":\"System.JSONException\",\"utf16Length\":8,\"input\":\"{\\\\\"a\\\\\":[1,\"}]';\nelse if((String)first.get('input') == '{\"a\":{\"b\":1,')expectedJSON='[{\"message\":\"Unexpected end-of-input within/between OBJECT entries at [line:1, column:25]\",\"type\":\"System.JSONException\",\"utf16Length\":12,\"input\":\"{\\\\\"a\\\\\":{\\\\\"b\\\\\":1,\"}]';\nelse if((String)first.get('input') == '{\"a\":[{\"b\":1')expectedJSON='[{\"message\":\"Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:37]\",\"type\":\"System.JSONException\",\"utf16Length\":12,\"input\":\"{\\\\\"a\\\\\":[{\\\\\"b\\\\\":1\"}]';\nelse if((String)first.get('input') == '{\"a\":{\"b\":\"unterminated')expectedJSON='[{\"message\":\"Unexpected end-of-input: was expecting closing quote for a string value at [line:1, column:47]\",\"type\":\"System.JSONException\",\"utf16Length\":23,\"input\":\"{\\\\\"a\\\\\":{\\\\\"b\\\\\":\\\\\"unterminated\"}]';\nelse {System.assert(false,'Unknown edge input/operation');return;}\ncompareExactEdgeValue(JSON.deserializeUntyped(expectedJSON),JSON.deserializeUntyped(JSON.serialize(rows)),'rows');\n}\nprivate static void compareExactEdgeValue(Object expected,Object actual,String path){\nif(expected instanceof Map<String,Object>){\n System.assert(actual instanceof Map<String,Object>,'Expected map '+path);\n Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n System.assertEquals(want.keySet(),got.keySet(),'Complete keys '+path);\n for(String key:want.keySet())compareExactEdgeValue(want.get(key),got.get(key),path+'.'+key);\n}else if(expected instanceof List<Object>){\n System.assert(actual instanceof List<Object>,'Expected list '+path);\n List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n System.assertEquals(want.size(),got.size(),'Complete phase population '+path);\n for(Integer i=0;i<want.size();i++)compareExactEdgeValue(want[i],got[i],path+'['+i+']');\n}else System.assertEquals(expected,actual,'Exact value '+path);\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonEOFEdges67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 12 || got.Passed != 12 || got.Failed != 0 || got.Skipped != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact source contracts failed: %s", data)
	}
}
